-- V13__seed_campsites_lots.sql
-- Seed campsites with images, facilities, and lots

-- Campsites
INSERT INTO campsites (id, owner_id, name, description, address, county, latitude, longitude, rating, review_count, featured, active, created_at, updated_at) VALUES
('00000000-0000-0000-0000-000000000101', '00000000-0000-0000-0001-000000000001', 'Clifden Eco Beach Camping', 'Stunning beachfront camping in the heart of Connemara. Wake up to panoramic views of the Atlantic Ocean and explore the Wild Atlantic Way.', 'Clifden, Connemara', 'Galway', 53.4892, -10.0195, 4.8, 124, TRUE, TRUE, '2022-01-15', '2022-01-15'),
('00000000-0000-0000-0000-000000000102', '00000000-0000-0000-0001-000000000002', 'Ring of Kerry Glamping', 'Luxury glamping experience with breathtaking mountain views. Perfect base for exploring the famous Ring of Kerry.', 'Killarney, Kerry', 'Kerry', 52.0599, -9.5044, 4.9, 89, TRUE, TRUE, '2021-06-01', '2021-06-01'),
('00000000-0000-0000-0000-000000000103', '00000000-0000-0000-0001-000000000003', 'Wicklow Mountains Retreat', 'Escape to the Wicklow Mountains for a peaceful camping experience. Close to Glendalough and numerous hiking trails.', 'Laragh, Wicklow', 'Wicklow', 53.0116, -6.3455, 4.6, 67, FALSE, TRUE, '2022-03-01', '2022-03-01'),
('00000000-0000-0000-0000-000000000104', '00000000-0000-0000-0001-000000000004', 'Dingle Peninsula Camp', 'Family-friendly campsite with stunning views of Dingle Bay. Great for water sports and dolphin watching.', 'Dingle, Kerry', 'Kerry', 52.1408, -10.2686, 4.7, 156, TRUE, TRUE, '2022-04-01', '2022-04-01'),
('00000000-0000-0000-0000-000000000105', '00000000-0000-0000-0001-000000000005', 'Burren Wild Camp', 'Unique camping experience in the lunar landscape of the Burren. Perfect for nature lovers and photographers.', 'Ballyvaughan, Clare', 'Clare', 53.1145, -9.1500, 4.5, 43, FALSE, TRUE, '2022-05-01', '2022-05-01'),
('00000000-0000-0000-0000-000000000106', '00000000-0000-0000-0001-000000000006', 'Giants Causeway Caravan Park', 'Award-winning park just minutes from the famous Giants Causeway. Ideal for exploring the Antrim Coast.', 'Bushmills, Antrim', 'Antrim', 55.2408, -6.5117, 4.8, 201, TRUE, TRUE, '2022-06-01', '2022-06-01');

